<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
final class UsageBillingView
{
    private static function h(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
    public static function money(?int $n):string{return$n===null?'Not configured':($n<0?'-':'').'₹'.number_format(intdiv(abs($n),100)).'.'.sprintf('%02d',abs($n)%100);}
    private static function hidden(string $k,string $v):string{return'<input type="hidden" name="'.self::h($k).'" value="'.self::h($v).'">';}
    private static function input(string $k,string $label,string $value='',string $type='text'):string{return'<label>'.self::h($label).'<input name="data['.self::h($k).']" value="'.self::h($value).'" type="'.$type.'"'.(in_array($k,['reference'],true)?'':' required').'></label>';}
    private static function select(string $k,string $label,array $items,string $selected=''):string{$s='<label>'.self::h($label).'<select name="data['.self::h($k).']">';foreach($items as$v=>$l)$s.='<option value="'.self::h($v).'"'.((string)$v===$selected?' selected':'').'>'.self::h($l).'</option>';return$s.'</select></label>';}
    private static function table(array $headers,array $rows):string{$s='<div class="ub-scroll" tabindex="0" aria-label="Scrollable demonstration records"><table><thead><tr>';foreach($headers as$h)$s.='<th>'.self::h($h).'</th>';$s.='</tr></thead><tbody>';foreach($rows as$r){$s.='<tr>';foreach($r as$c)$s.='<td>'.$c.'</td>';$s.='</tr>';}return$s.(!$rows?'<tr><td colspan="'.count($headers).'">No demonstration records for this selection.</td></tr>':'').'</tbody></table></div>';}
    private static function form(string $csrf,string $action,string $merchant,string $content,string $button):string{return'<form method="post" data-usage-form>'.self::hidden('_csrf',$csrf).self::hidden('action',$action).self::hidden('merchant',$merchant).self::hidden('request',bin2hex(random_bytes(16))).'<div class="ub-grid">'.$content.'</div><label>Reason<input name="reason" maxlength="240" required></label><label class="ub-confirm"><input type="checkbox" name="confirm" value="yes" required>I confirm this authorized synthetic change; no actual charges.</label><p role="alert" data-usage-error hidden></p><button>'.$button.'</button></form>';}
    public static function render(array $d,string $csrf,bool $platform,bool $catalogue=false):string
    {
        $h=fn($s)=>self::h($s);$money=fn($v)=>self::money($v===null?null:(int)$v);$title=$catalogue?'Usage & pricing workspace':'Merchant billing preview';
        $x='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$title.' · KIOS</title><link rel="stylesheet" href="/assets/usage-billing.css"><script src="/assets/usage-billing.js" defer></script></head><body class="platform-console usage-billing"><header class="ub-header"><a href="/merchant.php'.($platform?'?platform=overview':'').'" class="ub-logo">KIOS <span>'.($platform?'PLATFORM':'MERCHANT').'</span></a><nav aria-label="Billing preparation"><a href="/merchant.php'.($platform?'?platform=overview':'').'">Dashboard</a>'.($platform?'<a href="/merchant.php?usage_platform=1">Usage & pricing</a><a href="/merchant.php?platform=subscriptions">Subscription lifecycle</a>':'').'</nav><span class="ub-private">PRIVATE DEMO</span></header><main data-usage-billing><p class="ub-eyebrow">SaaS commercial foundation / Illustrative scenarios</p><h1>'.$title.'</h1><p class="ub-notice" role="note">'.UsageBilling::NOTICE.'</p><p class="ub-muted">Public ordering CLOSED · Registration, real charges, settlements and printing DISABLED.</p>';
        if($catalogue){
            $records=array_sum(array_column($d['usage'],'records'));$units=array_sum(array_column($d['usage'],'units'));$x.='<section class="ub-metrics"><article><span>Synthetic usage records</span><strong>'.$records.'</strong></article><article><span>Net simulated eligible units</span><strong>'.$units.'</strong></article><article><span>Actual charges created</span><strong>0</strong></article></section><nav class="ub-tabs" aria-label="Workspace sections"><a href="#merchants">Merchant estimates</a><a href="#pricing">Pricing manager</a><a href="#versions">Pricing history</a><a href="#policy">Calculation policy</a></nav><section id="merchants"><h2>Merchant estimates & usage</h2><p>Choose a merchant to inspect its ledger, adjustments and immutable saved estimates. Search the full <a href="/merchant.php?platform=merchants">merchant directory</a> if it is outside this first directory page.</p>';
            $rows=[];foreach($d['merchants']as$m)$rows[]=['<a href="/merchant.php?usage_platform=1&amp;merchant='.$h($m['merchant_id']).'">'.$h($m['name']).'</a>',$h($m['status']),$h($m['subscription']['assignment']['plan_id']??'See subscription')];$x.=self::table(['Merchant','Administrative access','Assigned plan'],$rows).'</section><section id="pricing"><h2>Subscription pricing manager</h2><p>Illustrative INR minor units (100 paise = ₹1). Plans remain versioned by the existing subscription engine. Configure monthly and annual scenarios separately; all values are assumptions.</p>';
            $choices=[];foreach($d['plans']as$p)$choices[$p['plan_id'].':'.$p['version']]=$p['name'].' · v'.$p['version'];
            $fields=self::select('choice','Existing immutable plan',$choices).self::select('cycle','Scenario cycle',['MONTHLY'=>'Monthly','ANNUAL'=>'Annual']).'<div class="ub-pricing-reference" data-pricing-heads="'.$h(json_encode($d['heads'])).'"></div>'.self::input('expected','Current pricing revision','0','number').self::input('subscription','Subscription price (paise)','100000','number').self::input('fee','Flat simulated-event fee (paise, maximum 300)','100','number').self::input('support','Optional support per period (paise)','0','number').self::input('effective','Effective UTC instant',gmdate('Y-m-01\T00:00'),'datetime-local');
            $x.=self::form($csrf,'usage-price','',$fields,'Save illustrative pricing version').'</section><section id="versions"><h2>Immutable pricing history & plan comparison</h2>';$rows=[];foreach($d['prices']as$p)$rows[]=[$h($p['plan_id'].' v'.$p['plan_version']),$h($p['cycle'].' / price v'.$p['version']),$money($p['subscription_paise']),$money($p['fee_paise']),$money($p['support_paise']),$h(gmdate('d M Y H:i',(int)$p['effective_epoch']).' UTC'),$h($p['reason'])];$x.=self::table(['Plan','Cycle / version','Subscription','Fee / simulated unit','Optional support','Effective','Reason'],$rows).'</section>';
        }else{
            $base='/merchant.php?'.($platform?'usage_platform=1':'usage=1').'&merchant='.rawurlencode($d['merchant']);$x.='<nav class="ub-tabs"><a href="#estimate">Estimate</a><a href="#ledger">Usage ledger</a><a href="#adjustments">Adjustment history</a><a href="#history">Saved history</a><a href="#reports">Reporting</a></nav><form method="get" class="ub-filter">'.self::hidden($platform?'usage_platform':'usage','1').self::hidden('merchant',$d['merchant']).'<label>UTC period<input type="month" name="period" value="'.$h($d['period']).'" required></label><label>Cycle<select name="cycle">';foreach(['MONTHLY','ANNUAL']as$v)$x.='<option'.($d['cycle']===$v?' selected':'').'>'.$v.'</option>';$x.='</select></label><label>Outlet<select name="outlet"><option value="all">All outlets — subscription counted once</option>';foreach($d['outlets']as$o)$x.='<option value="'.$h($o['outlet_id']).'"'.($d['outlet']===$o['outlet_id']?' selected':'').'>'.$h($o['name']).'</option>';$x.='</select></label><label>Support<select name="support"><option value="0"'.((int)$d['supportPaise']===0?' selected':'').'>Exclude optional support</option><option value="1"'.((int)$d['supportPaise']!==0?' selected':'').'>Include optional support</option></select></label><button>Review period</button></form>';
            $x.='<section id="estimate"><div class="ub-section-title"><div><h2>Reconciled demonstration scenario</h2><p>'.$h($d['assignment']['plan_id']??'No assignment').' · plan v'.$h($d['assignment']['plan_version']??'—').' · '.$h($d['lifecycle']).'</p></div><span class="ub-badge">'.($d['reconciles']?'PRICE CONFIGURED':'PRICING REQUIRED').'</span></div><p>Current assigned plan used as a scenario. No historical contract or actual amount due is asserted. UTC '.$h($d['period']).' · '.$h($d['cycle']).'</p><div class="ub-metrics"><article><span>Net eligible synthetic units</span><strong>'.$d['eligibleNetUnits'].'</strong></article><article><span>Hypothetical platform fees</span><strong>'.$money($d['usagePaise']).'</strong></article><article><span>Demonstration total</span><strong>'.$money($d['totalPaise']).'</strong></article></div>';
            $rows=[['Subscription',$money($d['subscriptionPaise'])],['Usage: '.$d['eligibleNetUnits'].' × '.($d['price']?$money($d['price']['fee_paise']):'not configured'),$money($d['usagePaise'])],['Optional support',$money($d['supportPaise'])],['Explicit adjustments / reversals',$money($d['adjustmentPaise'])],['Demonstration total',$money($d['totalPaise'])]];$x.=self::table(['Component — INR','Exact estimate'],$rows).'<p>Pricing version: '.$h($d['price']['price_id']??'none effective at period start').'. Source revision '.$d['sourceVersion'].'.</p></section>';
            if($platform){$x.='<section><h2>Controlled synthetic usage</h2><p>One SIMULATED_ELIGIBLE event = one hypothetical unit. Internal services, bill drafts and KOT events are excluded. Source IDs are unique within each merchant. No automatic import of operational orders occurs.</p>';$opts=[];foreach($d['outlets']as$o)$opts[$o['outlet_id']]=$o['name'];$fields=self::select('outlet','Verified outlet',$opts).self::input('source','Unique synthetic source ID','demo-'.bin2hex(random_bytes(5))).self::select('classification','Classification',array_combine(['SIMULATED_ELIGIBLE','INTERNAL_SERVICE','BILL_DRAFT','KOT','DEMO_EXCLUDED','ADJUSTMENT','REVERSAL'],['Simulated eligible unit','Internal service — excluded','Bill draft — excluded','KOT — excluded','Other demo — excluded','Explicit estimate adjustment','Reverse original event'])).self::input('occurred','Original event occurrence in UTC',gmdate('Y-m-d\TH:i'),'datetime-local').self::input('reference','Original event ID (reversal only)').self::input('amount','Signed adjustment (paise; zero for usage/reversal)','0','number').self::hidden('data[expected]',(string)$d['sourceVersion']);$x.=self::form($csrf,'usage-event',$d['merchant'],$fields,'Record synthetic event').'</section>';
            if($d['outlet']==='all'){$fields=self::hidden('data[period]',$d['period']).self::hidden('data[cycle]',$d['cycle']).self::hidden('data[support]',(string)((int)$d['supportPaise']!==0?1:0)).self::hidden('data[expected]',(string)$d['sourceVersion']);$x.='<section><h2>Preserve this estimate</h2><p>Creates an immutable demonstration snapshot. Later usage and pricing cannot alter saved history.</p>'.self::form($csrf,'usage-save',$d['merchant'],$fields,'Save demonstration estimate').'</section>';}}
            $rows=[];$adjust=[];foreach($d['ledger']as$e){$row=[$h($e['event_id']),$h($e['source_id']),$h($e['classification']),$h($e['outlet_id']),$h(gmdate('d M Y H:i',(int)$e['occurred_epoch']).' UTC'),$h($e['units']),$money($e['adjustment_paise']),$h($e['reference_id']??'—')];$rows[]=$row;if(in_array($e['classification'],['ADJUSTMENT','REVERSAL'],true))$adjust[]=$row;}$headers=['Event ID','Source','Classification','Outlet','UTC occurrence','Units','Adjustment','Reverses'];$x.='<section id="ledger"><h2>Usage ledger</h2><p>'.$d['syntheticRecords'].' records in selected period · page '.$d['page'].' of '.$d['pages'].' · 25 per page</p>'.self::table($headers,$rows);foreach(['Previous'=>max(1,$d['page']-1),'Next'=>min($d['pages'],$d['page']+1)]as$label=>$page)$x.='<a class="ub-page" href="'.$h($base.'&outlet='.$d['outlet'].'&period='.$d['period'].'&cycle='.$d['cycle'].'&page='.$page).'">'.$label.'</a>';$x.='</section><section id="adjustments"><h2>Adjustment & reversal history</h2><p>Current ledger page, with immutable references. Reverse the original UTC occurrence to correct its original period; the audit records when the correction was submitted.</p>'.self::table($headers,$adjust).'</section><section id="history"><h2>Saved demonstration history</h2>';$rows=[];foreach($d['history']as$record){$s=json_decode($record['snapshot_json'],true);$rows[]=[$h($record['preview_id']),$h($s['period'].' '.$s['cycle']),$h($s['createdUtc']),$h($s['sourceVersion']),$money($s['totalPaise'])];}$x.=self::table(['Snapshot','Period','Saved UTC','Source revision','Demonstration total'],$rows).'</section><section id="reports"><h2>Reporting workspace</h2><p>Authenticated JSON export includes this estimate, saved history and this ledger page. It contains no passwords, payment credentials or actual invoice. Change pages to inspect further ledger records.</p><a class="ub-button" href="'.$h($base.'&outlet='.$d['outlet'].'&period='.$d['period'].'&cycle='.$d['cycle'].'&support='.((int)$d['supportPaise']!==0?'1':'0').'&page='.$d['page'].'&export=json').'">Export authorized report</a></section>';
        }
        return$x.'<section id="policy"><h2>Calculation & eligibility policy</h2><p>'.self::h(UsageBilling::POLICY).'</p><p>All amounts use integer paise: no percentage fees, fractional units, taxes or floating-point rounding. Annual periods start 1 January. Corrections are full linked reversals; replacement events use a new source ID. Subscription/support are counted once in all-outlet scenarios. These examples do not define approved commercial tariffs.</p></section></main><footer>KIOS private demonstration · '.UsageBilling::NOTICE.'</footer></body></html>';
    }
}
